req=urllib.request.Request(url+f'/api/tools/{urllib.parse.quote(tool, safe=\"\")}/build?history_id=bbd44e69cb8906b51e60915d6b504cd1', headers={'x-api-key':key})
with urllib.request.urlopen(req, timeout=30) as r:
    obj=json.load(r)

def walk(x,path=''):
    if isinstance(x,dict):
        if 'name' in x and x.get('name')=='ref_file':
